// Generated by OrchestKit Claude Plugin
// Created: 2026-07-01

// Full doc-page Markdown reads, backed by the compiled Fumadocs source plus the
// hand-authored /docs/mcp and /docs/sdk landing pages. Split out of
// doc-search.ts so the NLWeb /ask endpoint (which needs only the lightweight
// search index) does not transitively load the heavy source at cold start.
// Used by the MCP full-content path (/api/mcp doc fetch) and the batch reads
// (POST /api/md/batch and its GET /api/jobs/<token> poll target).

import { readDocBody } from "@/lib/docs-content";
import { docsLandingPage, isDocsLandingSlug } from "@/lib/docs-landing-markdown";
import { source } from "@/lib/source";

export type DocPage = { title: string; markdown: string };

export type BatchResult =
	| ({ path: string; ok: true } & DocPage)
	| { path: string; ok: false; status: number; detail: string };

// Doc URLs are /docs/<slugs>; accept paths with or without the prefix, slashes
// or a `.md` suffix.
function toSlugs(pathOrSlug: string): string[] {
	const slugs = pathOrSlug
		.replace(/^\/+|\/+$/g, "")
		.replace(/\.md$/, "")
		.split("/")
		.filter(Boolean);
	return slugs[0] === "docs" ? slugs.slice(1) : slugs;
}

// Read one doc page by its URL path (e.g. "/docs/foo") or its slug
// ("foo/bar"). Returns null when the page doesn't exist.
export async function readDocPage(pathOrSlug: string): Promise<DocPage | null> {
	const slugs = toSlugs(pathOrSlug);
	const page = source.getPage(slugs);
	if (page) {
		const body = await readDocBody(page.slugs);
		return {
			title: page.data.title,
			markdown: `# ${page.data.title}\n\n${page.data.description ?? ""}\n\n${body ?? ""}\n`,
		};
	}
	if (slugs.length === 1 && isDocsLandingSlug(slugs[0])) return docsLandingPage(slugs[0]);
	return null;
}

export async function getDocMarkdown(pathOrSlug: string): Promise<string | null> {
	return (await readDocPage(pathOrSlug))?.markdown ?? null;
}

// Per-path failures are reported inline so one bad path does not fail the batch.
export function readDocBatch(paths: string[]): Promise<BatchResult[]> {
	return Promise.all(
		paths.map(async (path): Promise<BatchResult> => {
			const page = await readDocPage(path);
			if (!page) {
				return { path, ok: false, status: 404, detail: "No documentation page at this path." };
			}
			return { path, ok: true, ...page };
		}),
	);
}
